from build import build_items
I='/home/claude/studysheets/img33/'
D='📚 course slide · Lab 33 slides #'; G='📖 lab guide · Lab 33 notes, '
F56='Fig. 5-56 (orbit nerves, dorsal view)'; F55='Fig. 5-55 (maxillary nerve branches)'; F54='Fig. 5-54 (nerves at the tympano-occipital fissure)'; F53='Fig. 5-53 (brain, ventral view)'
items=[
('olfactory (first cranial) nerve',I+'s3.jpg','highlighted on the photo',D+'3','<b>CN I.</b> Not dissected: dozens of tiny fibers pass from the nasal mucosa through the <b>cribriform plate</b> to the <b>olfactory bulb</b>. Smell only.'),
('optic (second cranial) nerve',I+'s5.jpg','highlighted on the photo',D+'5','<b>CN II.</b> The thick nerve behind the eyeball, inside the retractor bulbi cone. It leaves through the <b>optic canal</b> and joins the <b>optic chiasm</b>. Vision.'),
('oculomotor (third cranial) nerve',I+'s7.jpg','highlighted on the photo',D+'7','<b>CN III.</b> Goes through the <b>orbital fissure</b>. It supplies the dorsal, medial and ventral recti, the ventral oblique and the levator palpebrae superioris. Its parasympathetic fibers synapse in the ciliary ganglion.'),
('ciliary ganglion',I+'s9.jpg','highlighted on the photo',D+'9','A small swelling at the <b>end of the oculomotor nerve</b>. It holds <b>parasympathetic</b> cell bodies whose fibers constrict the pupil.'),
('trochlear (fourth cranial) nerve',I+'s11.jpg','highlighted on the photo',D+'11','<b>CN IV.</b> Goes through the <b>orbital fissure</b> and supplies only the <b>dorsal oblique</b>. It is the only cranial nerve that leaves the <b>dorsal</b> brainstem.'),
('trigeminal (fifth cranial) nerve',I+'g5_0.png','"Trigeminal nerve V" (bottom of the drawing)',G+F56,'<b>CN V</b>, from the pons. It splits into 3: <b>ophthalmic (V1)</b> through the orbital fissure, <b>maxillary (V2)</b> through the round foramen, and <b>mandibular (V3)</b> through the oval foramen.'),
('ophthalmic nerve',I+'g5_0.png','"Ophthalmic nerve of V"',G+F56,'<b>V1</b>, sensory only. It goes through the <b>orbital fissure</b> and splits into the frontal, infratrochlear, ethmoidal and long ciliary nerves.'),
('frontal nerve',I+'g5_0.png','"Frontal nerve"',G+F56,'A branch of the ophthalmic nerve. It runs rostrally <b>between the dorsal oblique and the dorsal rectus</b> to the upper eyelid and forehead skin.'),
('infratrochlear nerve',I+'g5_0.png','"Infratrochlear nerve"',G+F56,'A branch of the ophthalmic nerve. It passes <b>under the trochlea</b> to the medial corner of the eye.'),
('ciliary nerves',I+'s17.jpg','highlighted on the photo',D+'17','Long ciliary nerves (from V1) run <b>along the optic nerve</b> to the eyeball. They carry sensation from the cornea and sympathetic fibers to the dilator pupillae.'),
('ethmoidal nerve',I+'g5_0.png','"Ethmoidal nerve"',G+F56,'A branch of the ophthalmic nerve. It goes through the <b>ethmoidal foramen and cribriform plate</b> to the nasal mucosa.'),
('maxillary nerve',I+'s20.jpg','highlighted on the photo',D+'20','<b>V2</b>, sensory. It runs through the <b>round foramen into the alar canal</b> and comes out in the pterygopalatine fossa, where it gives off zygomatic, pterygopalatine and infraorbital branches.'),
('zygomatic nerve',I+'s22.jpg','highlighted on the photo',D+'22','The first branch of the <b>maxillary nerve</b>. It enters the <b>periorbita</b> and carries sensation from the lateral eyelids and skin.'),
('pterygopalatine ganglion',I+'s24.jpg','at the green highlight (the ganglion sits right on this nerve)',D+'24','A <b>parasympathetic</b> ganglion dorsal to the maxillary nerve, on the medial pterygoid muscle. Its fibers go to the <b>lacrimal, nasal and palatine glands</b>.'),
('pterygopalatine nerve',I+'s24.jpg','highlighted on the photo',D+'24','Comes off the <b>ventral side of the maxillary nerve</b> and draws fibers from the pterygopalatine ganglion. It splits into the minor palatine, major palatine and caudal nasal nerves.'),
('minor palatine nerve',I+'g4_1.png','"Minor palatine nerve" (bottom of the drawing)',G+F55,'A branch of the pterygopalatine nerve going to the <b>soft palate</b>.'),
('major palatine nerve',I+'g4_1.png','"Major palatine nerve"',G+F55,'A branch of the pterygopalatine nerve. It runs through the <b>palatine canal</b> to the <b>hard palate</b> via the major palatine foramen.'),
('caudal nasal nerve',I+'g4_1.png','"Caudal nasal nerve"',G+F55,'A branch of the pterygopalatine nerve. It goes through the <b>sphenopalatine foramen</b> to the nasal mucosa.'),
('infraorbital nerve',I+'s29.jpg','highlighted on the photo',D+'29','What the <b>maxillary nerve becomes</b> after the pterygopalatine nerve leaves it. It runs through the <b>maxillary foramen, infraorbital canal and infraorbital foramen</b> to the upper lip and nose.'),
('superior alveolar branches',I+'g4_1.png','"Superior alveolar nerve" (bottom of the drawing)',G+F55,'Branches off the <b>infraorbital nerve inside the infraorbital canal</b>. They supply the <b>upper teeth</b>.'),
('abducent (sixth cranial) nerve',I+'s32.jpg','highlighted on the photo',D+'32','<b>CN VI.</b> Goes through the <b>orbital fissure</b> and supplies the <b>lateral rectus</b> and the <b>retractor bulbi</b> ("LR6").'),
('facial (seventh cranial) nerve',I+'s33.jpg','labeled branches on the slide',D+'33','<b>CN VII.</b> It enters the <b>internal acoustic meatus</b> and exits the <b>stylomastoid foramen</b>. It supplies the muscles of facial expression (auriculopalpebral, dorsal and ventral buccal branches).'),
('vestibulocochlear (eighth cranial) nerve',I+'g3_0.png','"VIII" (left side of the brainstem)',G+F53,'<b>CN VIII.</b> It enters the <b>internal acoustic meatus</b> with CN VII and ends in the inner ear, so you can\'t dissect it. It carries hearing and balance.'),
('distal ganglion of the vagus',I+'s36.jpg','highlighted on the photo',D+'36','Just outside the <b>tympano-occipital fissure</b>, caudal to the cranial cervical ganglion. It holds <b>visceral sensory</b> cell bodies. The transcript and Pre-Lab 33 call it parasympathetic.'),
('cranial cervical ganglion',I+'s38.jpg','highlighted on the photo',D+'38','The most cranial <b>sympathetic</b> ganglion. It sits next to the distal vagal ganglion; together they lead into the <b>vagosympathetic trunk</b>.'),
('glossopharyngeal (ninth cranial) nerve',I+'s40.jpg','highlighted on the photo',D+'40','<b>CN IX.</b> Goes through the <b>jugular foramen and tympano-occipital fissure</b> to the tongue (caudal third) and the pharynx. Expose it by cutting the longus capitis.'),
('vagus (tenth cranial) nerve',I+'s42.jpg','highlighted on the photo',D+'42','<b>CN X.</b> Goes through the <b>jugular foramen and tympano-occipital fissure</b> and joins the sympathetic trunk as the vagosympathetic trunk down the neck.'),
('proximal ganglion of the vagus',I+'g4_0.png','not visible: it sits inside the jugular foramen (only the distal ganglion shows here)',G+F54,'The vagus has 2 ganglia. The <b>proximal ganglion</b> sits <b>inside the jugular foramen</b>, so you can\'t see it. The <b>distal ganglion</b> is outside.'),
('pharyngeal plexus',I+'s47.jpg','highlighted on the photo',D+'47','A network formed by branches of the <b>glossopharyngeal + vagus</b> (plus cranial cervical ganglion fibers). It supplies the <b>pharyngeal muscles</b>.'),
('cranial laryngeal nerve',I+'s49.jpg','highlighted on the photo',D+'49','Leaves the vagus at the <b>distal ganglion</b>. It supplies the <b>cricothyroid muscle</b> and the laryngeal mucosa.'),
('caudal laryngeal nerve',I+'s51.jpg','highlighted on the photo',D+'51','The end of the <b>recurrent laryngeal nerve</b>. It supplies <b>every laryngeal muscle except the cricothyroid</b>. The left recurrent loops around the aortic arch; the right loops around the right subclavian artery.'),
('accessory (eleventh cranial) nerve',I+'s53.jpg','highlighted on the photo',D+'53','<b>CN XI.</b> Goes through the <b>jugular foramen</b>. Its <b>ventral branch</b> supplies the sternocephalicus (mastoid part) and its <b>dorsal branch</b> supplies the trapezius.'),
('hypoglossal (twelfth cranial) nerve',I+'s55.jpg','highlighted on the photo',D+'55','<b>CN XII.</b> Goes through the <b>hypoglossal canal</b> and is motor to the tongue muscles. It crosses <b>lateral</b> to the external carotid artery; IX runs medial to it.'),
('ansa cervicalis',I+'g4_0.png','"Ansa cervicalis" (right side of the drawing)',G+F54,'A <b>loop between the hypoglossal nerve and C1</b>. Don\'t search for it; just know where it is.'),
]
build_items(33,'Cranial nerves',items)
